  const primary=drive_url||render_url;                 // Drive is durable; hcti is the fallback
  const rid=meta.run_id||('run-'+k);
  if(!byRun[rid]) byRun[rid]=Object.assign({},meta,{_p:[],_r:[]});
  byRun[rid]._p[meta.slide_index||0]=primary;
  byRun[rid]._r[meta.slide_index||0]=render_url;
}
const out=[];
for(const rid of Object.keys(byRun)){ const r=byRun[rid];
  const P=(r._p||[]).filter(Boolean), R=(r._r||[]).filter(Boolean); delete r._p; delete r._r;
  r.Photo_Link=P[0]||''; r.Photo_Links=P.join(','); r.render_url=R.join(',');

  // Same brain, same rules: whatever Brand_KB forbids must not reach a channel.
  const brief = $('Resolve Design Brief').first().json || {};
  const bans = String(brief.never_say || '').split(/[,;|\n]/).map(s => s.trim()).filter(s => s.length > 2);
  const blob = [r.facebook_post, r.instagram_post, r.linkedin_post, r.twitter_post, r.tiktok_caption]
    .map(x => String(x || '')).join('\n').toLowerCase();
  const hits = bans.filter(b => blob.indexOf(b.toLowerCase()) !== -1);
  if (String(r.twitter_post || '').length > 280) hits.push('twitter_post over 280 chars');
  r.brand = brief.brand || r.brand || 'navid';
  r.approval_token = brief.approval_token || '';
  r.compliance_status = hits.length ? 'BLOCKED' : 'PASS';
  r.compliance_notes = hits.join('; ');

  out.push({json:r}); }
return out;

// Normalises a Zernio inbound webhook into a canonical event.
// Brand resolution now lives in the Brand KB Registry sub-workflow, so this
// node only EXTRACTS - it never decides which knowledge base answers.

const p0 = $input.first().json;
const body = (p0 && p0.body && typeof p0.body === 'object') ? p0.body : p0;

const ev = String(body.event || body.type || '').toLowerCase();
const d = body.message || body.comment || body.data || {};
const dir = String(d.direction || '').toLowerCase();

// Only act on real inbound content. Receipts, typing, outgoing echoes are dropped.
const actionable = (ev === 'message.received' && dir !== 'outgoing') || (ev === 'comment.received');
if (!actionable) return [];

const acc = body.account || d.account || {};
const conv = body.conversation || {};
const platform = String(d.platform || acc.platform || body.platform || '').toLowerCase();
const accountId = acc.id || acc._id || acc.accountId || d.accountId || body.accountId || '';
const profileId = acc.profileId || d.profileId || body.profileId || '';
const profileName = acc.username || acc.displayName || acc.name || d.profileName || body.profileName || '';

const s = d.sender || d.from || d.author || d.user || d.commenter || {};
const conversation_id = d.conversationId || conv.id || conv._id || d.conversation_id || '';

const comment_id = (ev === 'comment.received')
  ? (d.id || d._id || d.commentId || d.commentUrn || d.urn || (d.comment && (d.comment.id || d.comment.urn)) || '')
  : (d.commentId || '');

function liNum(v){ const m = String(v || '').match(/urn:li:(?:activity|ugcPost|share):([0-9]+)/); return m ? m[1] : ''; }

let post_id = d.postId || d.post_id || d.mediaId || d.videoId || d.objectId || d.activityUrn ||
  d.objectUrn || d.postUrn || d.rootUrn || d.rootUri || d.shareUrn || d.parentId ||
  (d.post && (d.post.id || d.post.urn)) || '';
if (String(post_id).indexOf('urn:li:') !== -1) { const n = liNum(post_id); if (n) post_id = n; }
if (!post_id && comment_id) {
  const cid = String(comment_id);
  if (cid.indexOf('urn:li:') !== -1) { const n = liNum(cid); if (n) post_id = n; }
  else if (cid.indexOf('_') !== -1) { post_id = cid.split('_')[0]; }
}

let sender_id = s.id || s._id || s.userId || d.senderId || d.fromId || '';
if (!sender_id) sender_id = comment_id ? ('cmt:' + comment_id)
  : (conversation_id ? ('conv:' + conversation_id) : '');

const sender_name = s.name || s.username || s.fullName || s.displayName || d.senderName || d.fromName || '';
const sender_username = s.username || s.handle || s.screenName || s.screen_name || '';
const sender_pic = s.picture || s.avatar || s.profilePicture || s.image || s.avatarUrl || '';
const contact_id = s.contactId || conv.contactId || d.contactId || '';
const message = d.text || d.message || d.content || (d.comment && d.comment.text) || '';

function profileUrl(pl, uname, sid){
  const u = String(uname || '').replace(/^@/, '').trim();
  const id = String(sid || '').replace(/^(cmt:|conv:)/, '');
  if (pl === 'twitter' || pl === 'x') return u ? 'https://twitter.com/' + u : '';
  if (pl === 'instagram') return u ? 'https://instagram.com/' + u : '';
  if (pl === 'facebook') return u ? 'https://facebook.com/' + u : (/^[0-9]+$/.test(id) ? 'https://facebook.com/' + id : '');
  if (pl === 'linkedin') return u ? 'https://www.linkedin.com/in/' + u : '';
  if (pl === 'tiktok') return u ? 'https://www.tiktok.com/@' + u : '';
  return '';
}

// ---- attachments (payload shape unverified; falls back to extension sniffing) ----
let attachment_url = '', attachment_type = '';
(function(){
  const cand = d.attachments || d.attachment || d.media || d.files || (d.message && d.message.attachments) || [];
  const a0 = Array.isArray(cand) ? (cand[0] || {}) : cand;
  if (a0 && typeof a0 === 'object') {
    attachment_url = a0.url || a0.link || a0.src || a0.fileUrl || a0.downloadUrl || (a0.payload && a0.payload.url) || '';
    const t = String(a0.type || a0.mediaType || a0.contentType || a0.mime || '').toLowerCase();
    if (/image|photo|jpe?g|png|gif|webp|sticker/.test(t)) attachment_type = 'image';
    else if (/audio|voice|ogg|mp3|m4a|wav|opus|aac|amr/.test(t)) attachment_type = 'audio';
  }
  if (!attachment_url) {
    if (d.image || d.imageUrl || d.photo) { attachment_url = d.image || d.imageUrl || d.photo; attachment_type = attachment_type || 'image'; }
    else if (d.audio || d.voice || d.audioUrl || d.voiceUrl) { attachment_url = d.audio || d.voice || d.audioUrl || d.voiceUrl; attachment_type = attachment_type || 'audio'; }
  }
  if (attachment_url && !attachment_type) {
    const u = String(attachment_url).toLowerCase().split('?')[0];
    if (/\.(jpe?g|png|gif|webp|bmp)$/.test(u)) attachment_type = 'image';
    else if (/\.(ogg|mp3|m4a|wav|opus|aac|amr)$/.test(u)) attachment_type = 'audio';
  }
  if (attachment_url && !/^https:\/\//i.test(String(attachment_url))) { attachment_url = ''; attachment_type = ''; }
})();

// ---- idempotency key: same webhook delivered twice must not reply twice ----
function hash(str){
  let h = 5381;
  const s2 = String(str || '');
  for (let i = 0; i < s2.length; i++) h = ((h * 33) ^ s2.charCodeAt(i)) >>> 0;
  return h.toString(36);
}
const platformEventId = d.id || d._id || d.messageId || d.mid || d.commentId || '';
const event_key = (platform + '|' + ev + '|' + (platformEventId ||
  (conversation_id + ':' + comment_id + ':' + hash(message + '|' + sender_id)))).slice(0, 180);

const MAX_MSG = 4000;

return [{ json: {
  event: ev, platform, accountId, profileId, profileName,
  conversation_id, comment_id, post_id,
  message: String(message).slice(0, MAX_MSG),
  message_truncated: String(message).length > MAX_MSG,
  sender_id, sender_name, sender_username, sender_pic, contact_id,
  profile_url: profileUrl(platform, sender_username, sender_id),
  attachment_url, attachment_type,
  event_key,
  received_at: new Date().toISOString()
} }];

// Merges the brand brief returned by the Brand KB Registry back onto the event.
// The registry throws if nothing matched, so reaching here means a real brand.

const ev = $('Dedupe Gate1').first().json;
const kb = $input.first().json || {};

if (!kb.resolved || !kb.brand) {
  throw new Error('Brand KB Registry returned no brand for profileId="' +
    (ev.profileId || '') + '" profileName="' + (ev.profileName || '') + '".');
}

return [{ json: Object.assign({}, ev, {
  brand: kb.brand,
  brand_name: kb.brand_name,
  kb: kb.kb,
  never_say: kb.never_say || '',
  escalation_email: kb.escalation_email || '',
  allow_auto_reply: kb.allow_auto_reply !== false,
  kb_matched_by: kb.matched_by || ''
}) }];

// Brand KB Registry - resolves a Zernio profile/account to a full brand brief.
// Called as a sub-workflow so every other workflow shares ONE source of truth.
//
// Input item may carry any of: profileId, profileName, accountId, platform, brand
// Output: one item with the resolved brief, or a thrown error naming what was seen.

const req = $input.first().json || {};

let rows = [];
try { rows = $('Read Brand_KB').all().map(i => i.json || {}); } catch (e) { rows = []; }
rows = rows.filter(r => r && String(r.brand || '').trim());

// Rows can be switched off without deleting them.
const active = rows.filter(r => String(r.active || 'yes').trim().toLowerCase() !== 'no');

function norm(v){ return String(v == null ? '' : v).trim().toLowerCase(); }
function splitList(v){
  return String(v || '').split(/[,;|\n]/).map(x => norm(x)).filter(Boolean);
}

const wantProfileId = norm(req.profileId);
const wantProfileNm = norm(req.profileName);
const wantAccountId = norm(req.accountId);
const wantBrand     = norm(req.brand);

function matches(row){
  const ids   = splitList(row.zernio_profile_id);
  const names = splitList(row.zernio_profile_names);
  const accts = splitList(row.zernio_account_ids);
  const brand = norm(row.brand);
  const bname = norm(row.brand_name);

  // Strongest signal first: an exact profile/account id.
  if (wantProfileId && ids.indexOf(wantProfileId) !== -1) return 'profile_id';
  if (wantAccountId && accts.indexOf(wantAccountId) !== -1) return 'account_id';
  if (wantBrand && (wantBrand === brand || wantBrand === bname)) return 'brand';

  // Weakest: fuzzy name. Zernio display names carry stray spaces and casing.
  if (wantProfileNm) {
    for (const n of names) {
      if (!n) continue;
      if (wantProfileNm === n || wantProfileNm.indexOf(n) !== -1 || n.indexOf(wantProfileNm) !== -1) return 'profile_name';
    }
    if (wantProfileNm === brand || wantProfileNm === bname) return 'brand_name';
  }
  return null;
}

let hit = null, how = '';
for (const r of active) {
  const m = matches(r);
  if (m) { hit = r; how = m; break; }
}

if (!hit) {
  const seen = active.map(r => r.brand + '(' + (r.zernio_profile_names || '') + ')').join(', ');
  throw new Error(
    'Brand KB: no row matched. Looked for profileId="' + (req.profileId || '') +
    '" profileName="' + (req.profileName || '') + '" accountId="' + (req.accountId || '') +
    '". Active rows: ' + (seen || 'NONE - is the Brand_KB tab populated?') +
    '. Add the profile id to the matching row rather than letting another brand answer.'
  );
}

function txt(v){ return String(v == null ? '' : v).trim(); }
function bool(v, dflt){
  const s = norm(v);
  if (!s) return dflt;
  return ['yes','true','1','y'].indexOf(s) !== -1;
}

// Assemble the KB the model actually reads. Keeping facts and rules separate
// means the same row serves the reply engine and the content engine.
const parts = [];
if (txt(hit.kb)) parts.push(txt(hit.kb));
if (txt(hit.services)) parts.push('SERVICES: ' + txt(hit.services));
if (txt(hit.faq)) parts.push('COMMON QUESTIONS AND APPROVED ANSWERS:\n' + txt(hit.faq));
if (txt(hit.never_say)) parts.push('NEVER SAY / NEVER PROMISE: ' + txt(hit.never_say));

return [{ json: {
  resolved: true,
  matched_by: how,
  brand: txt(hit.brand),
  brand_name: txt(hit.brand_name) || txt(hit.brand),
  kb: parts.join('\n\n'),
  kb_facts: txt(hit.kb),
  services: txt(hit.services),
  faq: txt(hit.faq),
  never_say: txt(hit.never_say),
  brand_tone: txt(hit.tone),
  brand_audience: txt(hit.audience),
  brand_focus: txt(hit.focus),
  anti_hype: txt(hit.anti_hype),
  visual_style: txt(hit.visual_style),
  hashtags: txt(hit.hashtags),
  escalation_email: txt(hit.escalation_email),
  allow_auto_reply: bool(hit.allow_auto_reply, true),
  zernio_profile_id: txt(hit.zernio_profile_id),
  zernio_profile_names: txt(hit.zernio_profile_names)
} }];

// Stops the flow when this exact webhook was already processed.
// Zernio retries deliveries; without this the customer gets replied to twice.

const ev = $('Parse Event').first().json;

let rows = [];
try { rows = $('Lookup Event Log1').all().map(i => i.json || {}); } catch (e) { rows = []; }
// alwaysOutputData injects an empty object when the filter matches nothing.
rows = rows.filter(r => r && String(r.event_key || '').trim());

const seen = rows.some(r => String(r.event_key) === String(ev.event_key));
if (seen) return [];   // 0 items ends this branch cleanly

return [{ json: ev }];

