// One HTML page for every outcome: the confirmation step, the result, and errors.
// Only one branch ever reaches here, so read whichever decision node actually ran.
const APPROVAL_BASE = 'https://N8N-HOST.example.com/webhook/watad-approval';

const req = $('Parse Approval Request').first().json || {};
let dec = null;
try { dec = $('Decide Content').first().json; } catch (e) { dec = null; }
if (!dec) { try { dec = $('Decide Reply').first().json; } catch (e) { dec = null; } }

function esc(t){
  return String(t == null ? '' : t)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

let tone, title, body, cta = '';

if (!req.valid) {
  tone = '#C0392B'; title = 'Link not usable'; body = req.message || 'This approval link is malformed.';
} else if (req.needs_confirm) {
  const isApprove = req.action === 'approve';
  tone = isApprove ? '#00A38C' : '#C0392B';
  title = isApprove ? 'Approve this?' : 'Reject this?';
  body = isApprove
    ? 'It will be scheduled automatically within the next 5 minutes.'
    : 'Nothing will be published or sent.';
  const url = APPROVAL_BASE +
    '?entity=' + encodeURIComponent(req.entity) +
    '&run_id=' + encodeURIComponent(req.run_id) +
    '&token=' + encodeURIComponent(req.token) +
    '&action=' + encodeURIComponent(req.action) +
    '&confirm=1';
  cta = '<a href="' + esc(url) + '" style="display:inline-block;background:' + tone +
        ';color:#fff;padding:16px 34px;border-radius:10px;text-decoration:none;font-weight:800;font-size:15px">' +
        (isApprove ? 'YES, APPROVE' : 'YES, REJECT') + '</a>';
} else {
  tone = (dec && dec.ok) ? '#00A38C' : '#8A98A6';
  title = (dec && dec.ok) ? 'Done' : 'No change';
  body = (dec && dec.message) || 'Nothing happened.';
}

const html = '<!DOCTYPE html><html><head><meta charset="utf-8">' +
  '<meta name="viewport" content="width=device-width,initial-scale=1">' +
  '<title>' + esc(title) + '</title></head>' +
  '<body style="margin:0;background:#F7F9FC;font-family:Helvetica,Arial,sans-serif">' +
  '<div style="max-width:520px;margin:12vh auto;background:#fff;border-radius:16px;' +
  'border-top:4px solid ' + tone + ';padding:44px;text-align:center;box-shadow:0 2px 10px rgba(15,29,45,.06)">' +
  '<div style="font-size:12px;letter-spacing:3px;color:#9AA7B4;text-transform:uppercase;font-weight:800">Watad Unified Engine</div>' +
  '<h1 style="margin:20px 0 10px;font-size:26px;color:#0F1D2D">' + esc(title) + '</h1>' +
  '<p style="margin:0 0 26px;font-size:15px;line-height:23px;color:#71808F">' + esc(body) + '</p>' +
  (dec && dec.topic ? '<p style="font-size:13px;color:#0F1D2D;background:#F4F7FA;border-radius:10px;padding:14px 16px;margin:0 0 26px">' + esc(dec.topic) + '</p>' : '') +
  cta +
  '<p style="margin:28px 0 0;font-size:12px;color:#9AA7B4">' + esc(req.run_id || '') + '</p>' +
  '</div></body></html>';

return [{ json: { html } }];
